// Renders assets/mxcord-logo.svg to a PNG and writes it to core/logo.js for both clients.
// Run `npm run logo` after changing the SVG.
import { readFile, writeFile } from "node:fs/promises";
import { Resvg } from "@resvg/resvg-js";

const SIZE_PX = 64;

const svg = await readFile(new URL("../assets/mxcord-logo.svg", import.meta.url), "utf8");
const png = new Resvg(svg, { fitTo: { mode: "height", value: SIZE_PX } }).render().asPng();
await writeFile(new URL("../core/logo.js", import.meta.url), [
    "// Generated by tools/gen-logo.mjs from assets/mxcord-logo.svg. Do not edit.",
    `export const LOGO_PNG_B64 = "${Buffer.from(png).toString("base64")}";`,
    "export const LOGO_URI = `data:image/png;base64,${LOGO_PNG_B64}`;",
    "",
].join("\n"));
console.log(`Wrote ${png.length}-byte logo`);
